/// 広義単調増加する最大連続区間を [l, r) で返す。
#[rustfmt::skip]
#[inline(always)]
pub fn non_decreasing_ranges<T: Ord>(a: &[T]) -> Vec<(usize, usize)> {
    let n = a.len();
    if n == 0 { return Vec::new(); }

    let mut res = Vec::new();
    let mut l = 0;
    for i in 1..n {
        if a[i - 1] > a[i] {
            res.push((l, i));
            l = i;
        }
    }

    res.push((l, n));
    return res;
}

/// 狭義単調増加する最大連続区間を [l, r) で返す。
#[rustfmt::skip]
#[inline(always)]
pub fn increasing_ranges<T: Ord>(a: &[T]) -> Vec<(usize, usize)> {
    let n = a.len();
    if n == 0 { return Vec::new(); }

    let mut res = Vec::new();
    let mut l = 0;

    for i in 1..n {
        if a[i - 1] >= a[i] {
            res.push((l, i));
            l = i;
        }
    }

    res.push((l, n));
    return res;
}

/// 隣接する2要素が `f(prev, next)` を満たし続ける最大区間を返す。
#[rustfmt::skip]
#[inline(always)]
pub fn monotonic_ranges<T, F>(a: &[T], mut f: F) -> Vec<(usize, usize)>
where F: FnMut(&T, &T) -> bool
{
    if a.is_empty() { return Vec::new(); }
    let mut res = Vec::new();
    let mut l = 0;

    for i in 1..a.len() {
        if !f(&a[i - 1], &a[i]) {
            res.push((l, i));
            l = i;
        }
    }

    res.push((l, a.len()));
    return res;
}

