/// LISの本体 O(N logN)
/// strict: true→狭義単調増加 false→広義単調増加
/// return: (index, dp)
///     → index: 最長部分列を構成するインデックス(昇順)
///     → dp[i]: a[i]を末尾とする最長部分列の長さ
#[rustfmt::skip]
pub fn lis_core<T: Ord>(a: &[T], strict: bool) -> (Vec<usize>, Vec<usize>) {
    const NONE: usize = usize::MAX;
    let n = a.len();

    // tail[k]=長さk+1の部分列の末尾として最小の値を持つ要素のインデックス
    let mut tail: Vec<usize> = Vec::new();
    let mut prev = vec![NONE; n];
    let mut dp = vec![0; n];

    for i in 0..n {
        let pos = if strict { 
            tail.partition_point(|&j| a[j] < a[i]) 
        } else { 
            tail.partition_point(|&j| a[j] <= a[i]) 
        };
        
        dp[i] = pos + 1;
        if pos > 0 { prev[i] = tail[pos - 1]; }
        if pos == tail.len() { tail.push(i); } else { tail[pos] = i; }
    }

    // 復元
    let mut index = Vec::with_capacity(tail.len());
    let mut current = tail.last().copied().unwrap_or(NONE);
    while current != NONE {
        index.push(current);
        current = prev[current];
    }
    index.reverse();
    return (index, dp);
}

/// 狭義単調増加する最長部分列のインデックスを返す
#[inline(always)]
pub fn increasing_subsequence<T: Ord>(a: &[T]) -> Vec<usize> {
    lis_core(a, true).0
}

/// 広義単調増加する最長部分列のインデックスを返す
#[inline(always)]
pub fn non_decreasing_subsequence<T: Ord>(a: &[T]) -> Vec<usize> {
    lis_core(a, false).0
}

/// dp[i] = a[i] で終わる狭義単調増加部分列の最大長
#[inline(always)]
pub fn increasing_subsequence_dp<T: Ord>(a: &[T]) -> Vec<usize> {
    lis_core(a, true).1
}

/// dp[i] = a[i] で終わる広義単調増加部分列の最大長
#[inline(always)]
pub fn non_decreasing_subsequence_dp<T: Ord>(a: &[T]) -> Vec<usize> {
    lis_core(a, false).1
}

/// `f(prev, next)` を満たし続ける最長部分列のインデックスを返す。O(N^2)
///
/// f は任意の条件でよい（例: `|x, y| y - x <= 3`）。
/// 単純な大小比較なら O(N log N) の関数を使うこと。
#[rustfmt::skip]
pub fn monotonic_subsequence<T, F>(a: &[T], mut f: F) -> Vec<usize>
where
    F: FnMut(&T, &T) -> bool,
{
    const NONE: usize = usize::MAX;
    let n = a.len();
    if n == 0 { return Vec::new(); }

    let mut dp = vec![1_usize; n];
    let mut prev = vec![NONE; n];

    for i in 0..n {
        for j in 0..i {
            if dp[j] + 1 > dp[i] && f(&a[j], &a[i]) {
                dp[i] = dp[j] + 1;
                prev[i] = j;
            }
        }
    }

    let mut current = (0..n).max_by_key(|&i| dp[i]).unwrap();
    let mut index = Vec::new();
    while current != NONE {
        index.push(current);
        current = prev[current];
    }
    index.reverse();
    return index;
}
